const out = $input.first().json; const steps = out.intermediateSteps || [];
const rmap = { sec_figures: 'numbers', filing_search: 'filings', web_search: 'web' };
const tools = steps.map(s => s.action?.tool || '');
const inputs = steps.map(s => JSON.stringify(s.action?.toolInput || {}));
const parts = steps.map((s, i) => { const ti = s.action?.toolInput || {}; const r = rmap[tools[i]] || tools[i]; return { q: inputs[i].slice(0, 140), route: r, mode: r === 'filings' ? 'kb' : r, ticker: ti.ticker ? String(ti.ticker).toUpperCase() : null }; });
const answer = String(out.output || '').trim();
const tickers = new Set(parts.map(p => p.ticker).filter(Boolean));
const metrics = new Set(steps.filter(s => s.action?.tool === 'sec_figures').map(s => (s.action.toolInput || {}).metric));
let route = (tickers.size >= 2 || metrics.size >= 2) ? 'compound' : (parts[0]?.route || 'direct');   // compound = several companies or several metrics, not just repeated searches
let mode = route === 'compound' ? 'compound' : (parts[0]?.mode || 'direct');
if (!steps.length && /(not one of|isn't one of|not covered|isn't covered|don't cover|do not cover)/i.test(answer)) mode = 'out_of_scope';
const sources = [];
for (const s of steps) { try { const o = JSON.parse(typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation)); for (const u of (o.sources || [])) if (!sources.includes(u)) sources.push(u); } catch (e) {} }
return [{ json: { question: $('Question').first().json.question, answer, mode, route, ticker: parts[0]?.ticker || null, parts, sources, toolCalls: steps.length } }];

const COMPANIES = {"AAPL": {"name": "Apple", "cik": 320193}, "MSFT": {"name": "Microsoft", "cik": 789019}, "NVDA": {"name": "NVIDIA", "cik": 1045810}, "GOOGL": {"name": "Alphabet (Google)", "cik": 1652044}, "AMZN": {"name": "Amazon", "cik": 1018724}, "META": {"name": "Meta Platforms", "cik": 1326801}, "AVGO": {"name": "Broadcom", "cik": 1730168}, "TSLA": {"name": "Tesla", "cik": 1318605}, "ORCL": {"name": "Oracle", "cik": 1341439}, "NFLX": {"name": "Netflix", "cik": 1065280}, "AMD": {"name": "Advanced Micro Devices", "cik": 2488}, "CRM": {"name": "Salesforce", "cik": 1108524}, "ADBE": {"name": "Adobe", "cik": 796343}, "CSCO": {"name": "Cisco", "cik": 858877}, "IBM": {"name": "IBM", "cik": 51143}, "INTU": {"name": "Intuit", "cik": 896878}, "QCOM": {"name": "Qualcomm", "cik": 804328}, "TXN": {"name": "Texas Instruments", "cik": 97476}, "NOW": {"name": "ServiceNow", "cik": 1373715}, "PLTR": {"name": "Palantir", "cik": 1321655}};
const q = $json.query || {}; const t = String(q.ticker || '').toUpperCase(); const co = COMPANIES[t];
return [{ json: { ticker: t, metric: String(q.metric || 'revenue'), company: co?.name || null, cik10: co ? String(co.cik).padStart(10, '0') : null } }];

const d = $('Decide Route').first().json;
const facts = $json.facts || {};
const CANDIDATES = {
  revenue: [['us-gaap','RevenueFromContractWithCustomerExcludingAssessedTax'],['us-gaap','Revenues'],['us-gaap','SalesRevenueNet'],['us-gaap','RevenueFromContractWithCustomerIncludingAssessedTax']],
  net_income: [['us-gaap','NetIncomeLoss']],
  eps_diluted: [['us-gaap','EarningsPerShareDiluted']],
  operating_income: [['us-gaap','OperatingIncomeLoss']],
  gross_profit: [['us-gaap','GrossProfit']],
  rd_expense: [['us-gaap','ResearchAndDevelopmentExpense'],['us-gaap','ResearchAndDevelopmentExpenseExcludingAcquiredInProcessCost']],
  operating_cash_flow: [['us-gaap','NetCashProvidedByUsedInOperatingActivities']],
  cash: [['us-gaap','CashAndCashEquivalentsAtCarryingValue']],
  total_assets: [['us-gaap','Assets']],
  long_term_debt: [['us-gaap','LongTermDebtNoncurrent'],['us-gaap','LongTermDebt']],
};

// Pick the candidate concept with the most recent data (companies switch tags over time)
let best = null;
for (const [tax, name] of (CANDIDATES[d.metric] || [])) {
  const concept = facts[tax]?.[name];
  if (!concept) continue;
  const unit = Object.keys(concept.units || {})[0];
  const rows = (concept.units[unit] || []).filter(r => ['10-K', '10-Q', '10-K/A', '10-Q/A'].includes(r.form));
  if (!rows.length) continue;
  const latest = rows.reduce((m, r) => (r.end > m ? r.end : m), '');
  if (!best || latest > best.latest) best = { name, unit, rows, latest, label: concept.label };
}

if (!best) {
  return [{ json: { ...d, found: false } }];
}

// Dedupe by period, keep the latest-filed value, label duration (quarter / YTD / annual / point in time)
const byPeriod = {};
for (const r of best.rows) {
  const k = `${r.start || ''}|${r.end}`;
  if (!byPeriod[k] || r.filed > byPeriod[k].filed) byPeriod[k] = r;
}
const days = r => r.start ? Math.round((new Date(r.end) - new Date(r.start)) / 86400000) : 0;
const kind = r => { const n = days(r); if (!r.start) return 'as of'; if (n < 100) return 'quarter'; if (n > 350) return 'full year'; return `${Math.round(n / 30)}-month YTD`; };
const fmt = v => Math.abs(v) >= 1e6 ? `${(v / 1e9).toFixed(3)} billion` : String(v);

const rows = Object.values(byPeriod).sort((a, b) => b.end.localeCompare(a.end)).slice(0, 16);
const lines = rows.map(r =>
  `- ${kind(r)} ${r.start ? r.start + ' to ' : ''}${r.end}: ${fmt(r.val)} ${best.unit} (exact: ${r.val}; form ${r.form}, filed ${r.filed}, accession ${r.accn})`);

const context = `${d.company} (${d.ticker}) — ${best.label} [XBRL tag ${best.name}], unit ${best.unit}.\n` +
  `Source: SEC XBRL company facts. Use the period dates, NOT fiscal-year labels.\n` + lines.join('\n');

return [{ json: {
  ...d, found: true, mode: 'numbers', context,
  sources: [`https://data.sec.gov/api/xbrl/companyfacts/CIK${d.cik10}.json`],
}}];

const m = ($input.first().json.matches || []);
if (!m.length) return [{ json: { result: 'No passages found for that ticker and query.', sources: [] } }];
const result = m.map((h, i) => `[${i + 1}] ${h.company || ''} (${h.ticker || ''}) Form ${h.form || ''}, period ending ${h.reportDate || '?'}, filed ${h.filingDate || '?'}
${String(h.chunk_text || '').slice(0, 1500)}`).join('

---

');
return [{ json: { result, sources: [...new Set(m.map(h => h.url).filter(Boolean))] } }];

const r = ($input.first().json.results || []);
if (!r.length) return [{ json: { result: 'No web results found.', sources: [] } }];
const result = r.map((x, i) => `[W${i + 1}] ${x.title || ''} (${x.url})${x.published_at ? ' published ' + x.published_at : ''}
${x.snippet || x.description || ''}`).join('

---

').slice(0, 12000);
return [{ json: { result, sources: r.map(x => x.url).filter(Boolean) } }];
